package ru.evolenta.pgs.worker;

import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import javax.xml.stream.*;import java.time.*;import java.time.format.*;
import static ru.evolenta.pgs.worker.Util.*;

/** StAX reader. Never evaluates formulas, macros, external links or XML entities. */
public final class XlsxReader {
    public static final long MAX_FILE=20L*1024*1024,MAX_ENTRY=50L*1024*1024,MAX_TOTAL=100L*1024*1024;
    public static final List<String> NAMES=Collections.unmodifiableList(Arrays.asList("1. Титульный лист","2. Реестр мест размещения РК","3. Реестр разрешений","4. Реестр социальной рекламы","5. Реестр РК без разрешения","6.Реестр предписаний о демонтаж","7. Значения для копирования"));
    private static final Map<String,String> IMPLICIT=new HashMap<String,String>();
    static{IMPLICIT.put("sheet2:CG","82.1");IMPLICIT.put("sheet2:DA","100.2");IMPLICIT.put("sheet2:DH","106.2");IMPLICIT.put("sheet2:FU","171.1");IMPLICIT.put("sheet2:FV","172.2");IMPLICIT.put("sheet2:FW","173.3");IMPLICIT.put("sheet3:O","14.2");IMPLICIT.put("sheet3:P","14.3");IMPLICIT.put("sheet3:AF","29.1");IMPLICIT.put("sheet3:AG","29.2");}
    private final XMLInputFactory factory;
    private int parsedCells;private long parsedCharacters;
    public XlsxReader(){factory=XMLInputFactory.newFactory();factory.setProperty(XMLInputFactory.SUPPORT_DTD,false);factory.setProperty("javax.xml.stream.isSupportingExternalEntities",false);factory.setXMLResolver((publicID,systemID,baseURI,namespace)->{throw new XMLStreamException("External entity forbidden");});}
    private XMLStreamReader xml(ZipFile zip,String name)throws Exception{ZipEntry e=zip.getEntry(name);if(e==null)throw new IllegalArgumentException("В XLSX отсутствует "+name);byte[] b;try(InputStream in=zip.getInputStream(e)){b=readBounded(in,MAX_ENTRY);}return factory.createXMLStreamReader(new ByteArrayInputStream(b),"UTF-8");}
    private String attr(XMLStreamReader r,String n){for(int i=0;i<r.getAttributeCount();i++)if(r.getAttributeLocalName(i).equals(n))return r.getAttributeValue(i);return "";}
    private void secure(XMLStreamReader r)throws XMLStreamException{if(r.getEventType()==XMLStreamConstants.DTD||r.getEventType()==XMLStreamConstants.ENTITY_REFERENCE)throw new XMLStreamException("DTD/entities forbidden");}
    private Map<String,String> relationships(ZipFile zip,String part)throws Exception{String name=part.substring(0,part.lastIndexOf('/')+1)+"_rels/"+part.substring(part.lastIndexOf('/')+1)+".rels";Map<String,String> out=new LinkedHashMap<String,String>();if(zip.getEntry(name)==null)return out;XMLStreamReader r=xml(zip,name);try{while(r.hasNext()){r.next();secure(r);if(r.isStartElement()&&r.getLocalName().equals("Relationship")){if("External".equals(attr(r,"TargetMode")))continue;String target=attr(r,"Target");String resolved=resolve(part,target);out.put(attr(r,"Id"),resolved);}}}finally{r.close();}return out;}
    private static String resolve(String base,String target){String raw=target.startsWith("/")?target.substring(1):base.substring(0,base.lastIndexOf('/')+1)+target;Deque<String> stack=new ArrayDeque<String>();for(String p:raw.replace('\\','/').split("/")){if(p.equals("..")){if(stack.isEmpty())throw new IllegalArgumentException("ZIP path escape");stack.removeLast();}else if(!p.isEmpty()&&!p.equals("."))stack.add(p);}return String.join("/",stack);}
    private List<String> sharedStrings(ZipFile zip)throws Exception{List<String> strings=new ArrayList<String>();if(zip.getEntry("xl/sharedStrings.xml")==null)return strings;XMLStreamReader r=xml(zip,"xl/sharedStrings.xml");StringBuilder current=null;try{while(r.hasNext()){r.next();secure(r);if(r.isStartElement()&&r.getLocalName().equals("si"))current=new StringBuilder();else if(r.isStartElement()&&r.getLocalName().equals("t")&&current!=null)current.append(r.getElementText());else if(r.isEndElement()&&r.getLocalName().equals("si")){strings.add(current.toString());current=null;if(strings.size()>300000)throw new IllegalArgumentException("Слишком много строк XLSX");}}}finally{r.close();}return strings;}
    private SortedMap<Integer,Map<Integer,String>> rows(ZipFile zip,String part,List<String> shared)throws Exception{SortedMap<Integer,Map<Integer,String>> rows=new TreeMap<Integer,Map<Integer,String>>();XMLStreamReader r=xml(zip,part);int row=0,col=0;String type="";StringBuilder value=null;Map<Integer,String> cells=null;try{while(r.hasNext()){r.next();secure(r);if(r.isStartElement()){String name=r.getLocalName();if(name.equals("row")){row=Integer.parseInt(attr(r,"r"));if(row>1000000)throw new IllegalArgumentException("Row limit");cells=new TreeMap<Integer,String>();}else if(name.equals("c")){String ref=attr(r,"r");col=columnOrder(ref)-1;if(col<0||col>16383)throw new IllegalArgumentException("Invalid cell reference");type=attr(r,"t");value=new StringBuilder();}else if((name.equals("v")||name.equals("t"))&&value!=null)value.append(r.getElementText());}
            else if(r.isEndElement()){String name=r.getLocalName();if(name.equals("c")&&cells!=null&&value!=null){String text=value.toString();if(type.equals("s")){int index=Integer.parseInt(text);if(index<0||index>=shared.size())throw new IllegalArgumentException("Invalid shared string");text=shared.get(index);}if(!text.isEmpty())cells.put(col,text);value=null;}else if(name.equals("row")&&cells!=null){if(row<=5||!cells.isEmpty())rows.put(row,cells);if(rows.size()>6000)throw new IllegalArgumentException("Превышен лимит строк XLSX");cells=null;}}}}finally{r.close();}return rows;}
    private Set<String> embedded(ZipFile zip,String sheet)throws Exception{Set<String> cells=new HashSet<String>();Map<String,String> rel=relationships(zip,sheet);List<String> drawings=new ArrayList<String>();XMLStreamReader r=xml(zip,sheet);try{while(r.hasNext()){r.next();secure(r);if(r.isStartElement()){String n=r.getLocalName();if(n.equals("drawing")&&rel.containsKey(attr(r,"id")))drawings.add(rel.get(attr(r,"id")));if((n.equals("oleObject")||n.equals("control"))&&present(attr(r,"ref")))cells.add(attr(r,"ref"));}}}finally{r.close();}
        for(String drawing:drawings){r=xml(zip,drawing);int col=-1,row=-1;boolean from=false;try{while(r.hasNext()){r.next();secure(r);if(r.isStartElement()){String n=r.getLocalName();if(n.equals("from")){from=true;col=row=-1;}else if(from&&n.equals("col"))col=Integer.parseInt(r.getElementText());else if(from&&n.equals("row"))row=Integer.parseInt(r.getElementText());}else if(r.isEndElement()&&r.getLocalName().equals("from")){if(col>=0&&row>=0)cells.add(columnName(col)+(row+1));from=false;}}}finally{r.close();}}
        return cells;
    }
    private static String raw(Map<Integer,String> row,int col){return row==null?"":text(row.get(col));}
    public static String businessValue(String value,String field){String k=key(field),s=clean(value);boolean date=k.contains("дата")||k.contains("числа"),time=k.contains("время");if(s.matches("-?\\d+(\\.\\d+)?")){double n=Double.parseDouble(s);if(date&&n>=1&&n<=80000)return LocalDate.of(1899,12,30).plusDays((long)n).format(DateTimeFormatter.ofPattern("dd.MM.uuuu"));if(time){long m=Math.round((n-Math.floor(n))*1440)%1440;return String.format("%02d:%02d",m/60,m%60);}}
        if(date&&s.matches("\\d{4}-\\d{2}-\\d{2}(T.*)?"))return s.substring(8,10)+"."+s.substring(5,7)+"."+s.substring(0,4);
        if(time&&s.matches("\\d{1,2}:\\d{2}(:\\d{2}(\\.\\d+)?)?")){String[] p=s.split(":");return String.format("%02d:%s",Integer.parseInt(p[0]),p[1]);}
        if(time&&s.startsWith("PT"))try{Duration d=Duration.parse(s);return String.format("%02d:%02d",d.toHours(),d.toMinutes()%60);}catch(Exception ignored){}
        return value;
    }
    private Map<String,Object> business(SortedMap<Integer,Map<Integer,String>> source,String name,String code,Set<String> embedded)throws IOException{List<Object> columns=new ArrayList<Object>(),data=new ArrayList<Object>();int width=0;for(int row=2;row<=5;row++)if(source.containsKey(row)&&!source.get(row).isEmpty())width=Math.max(width,Collections.max(source.get(row).keySet())+1);String block="",sub="";
        for(int i=0;i<width;i++){if(present(raw(source.get(2),i)))block=raw(source.get(2),i);if(present(raw(source.get(3),i)))sub=raw(source.get(3),i);String field=raw(source.get(4),i),letter=columnName(i);if(!present(field))continue;String a=clean(raw(source.get(1),i));if(a.isEmpty())a=text(IMPLICIT.get(code+":"+letter));if(key(a).equals("№")||key(field).equals("название поля"))continue;columns.add(obj("index",i,"column",letter,"attribute",a,"block",block,"subBlock",sub,"fieldName",field,"requiredMarker",raw(source.get(5),i)));}
        for(Map.Entry<Integer,Map<Integer,String>> entry:source.entrySet()){int n=entry.getKey();if(n<6)continue;List<Object> cells=new ArrayList<Object>();for(Object o:columns){Map<String,Object> c=map(o);String letter=clean(c.get("column"));String value=businessValue(raw(entry.getValue(),integer(c.get("index"))),clean(c.get("fieldName")));boolean object=embedded.contains(letter+n);if(!value.isEmpty()||object){parsedCells++;parsedCharacters+=value.length();if(parsedCells>500000||parsedCharacters>32L*1024*1024)throw new IllegalArgumentException("Превышен безопасный объём содержимого XLSX; разделите данные на несколько файлов");cells.add(obj("column",letter,"value",value,"embeddedObject",object));}}if(!cells.isEmpty())data.add(obj("rowNumber",n,"cells",cells));}
        return obj("code",code,"sheetName",name,"headerRow",4,"dataStartRow",6,"columns",columns,"rows",data,"rowCount",data.size());
    }
    private Map<String,Object> references(SortedMap<Integer,Map<Integer,String>> rows){int header=3;for(Map.Entry<Integer,Map<Integer,String>> e:rows.entrySet())if(e.getKey()<=5&&e.getValue().values().stream().anyMatch(x->key(x).equals("субъекты рф"))){header=e.getKey();break;}List<Object> entries=new ArrayList<Object>();Map<Integer,String> h=rows.get(header);if(h!=null)for(Map.Entry<Integer,String> c:h.entrySet()){LinkedHashMap<String,String> values=new LinkedHashMap<String,String>();for(Map.Entry<Integer,Map<Integer,String>> r:rows.entrySet())if(r.getKey()>header){String v=raw(r.getValue(),c.getKey());if(present(v)&&!values.containsKey(key(v)))values.put(key(v),v);}entries.add(obj("name",clean(c.getValue()),"values",new ArrayList<String>(values.values())));}return obj("formatVersion","xml-safe-v1","entries",entries);}
    public Map<String,Object> parse(byte[] bytes,Map<String,Object> file,Map<String,Object> context)throws Exception{
        parsedCells=0;parsedCharacters=0;
        if(bytes.length==0||bytes.length>MAX_FILE)throw new IllegalArgumentException("Пустой XLSX или размер более 20 МБ");Path temp=Files.createTempFile("pgs-xlsx-",".xlsx");try{Files.write(temp,bytes);try(ZipFile zip=new ZipFile(temp.toFile())){long total=0;int count=0;Set<String> names=new HashSet<String>();Enumeration<? extends ZipEntry> it=zip.entries();byte[] buffer=new byte[8192];while(it.hasMoreElements()){ZipEntry e=it.nextElement();if(++count>10000||!names.add(e.getName())||e.getName().contains("..")||e.getName().contains("\\"))throw new IllegalArgumentException("Некорректная структура ZIP");if(e.getSize()>MAX_ENTRY)throw new IllegalArgumentException("ZIP entry > 50 MB");long actual=0;try(InputStream in=zip.getInputStream(e)){int n;while((n=in.read(buffer))!=-1){actual+=n;total+=n;if(actual>MAX_ENTRY||total>MAX_TOTAL)throw new IllegalArgumentException("Превышен лимит распаковки XLSX");}}if(e.getSize()>=0&&actual!=e.getSize())throw new IllegalArgumentException("ZIP size mismatch");}
            List<String> shared=sharedStrings(zip);Map<String,String> rel=relationships(zip,"xl/workbook.xml");LinkedHashMap<String,String> sheets=new LinkedHashMap<String,String>();XMLStreamReader r=xml(zip,"xl/workbook.xml");try{while(r.hasNext()){r.next();secure(r);if(r.isStartElement()&&r.getLocalName().equals("sheet")){String name=attr(r,"name"),part=rel.get(attr(r,"id"));if(part==null||sheets.put(name,part)!=null)throw new IllegalArgumentException("Некорректный лист XLSX");}}}finally{r.close();}
            if(!new ArrayList<String>(sheets.keySet()).equals(NAMES))throw new IllegalArgumentException("Структура файла изменена. Загрузите корректный шаблон миграции рекламы.");
            List<Object> business=new ArrayList<Object>();int rowCount=0;for(int n=2;n<=6;n++){String name=NAMES.get(n-1),part=sheets.get(name);Map<String,Object> sheet=business(rows(zip,part,shared),name,"sheet"+n,embedded(zip,part));business.add(sheet);rowCount+=integer(sheet.get("rowCount"));}if(rowCount==0||rowCount>5000)throw new IllegalArgumentException("В XLSX должно быть от 1 до 5000 строк данных");
            Map<String,Object> f=copy(file);f.put("id",first(file.get("_id"),file.get("id"),file.get("fileId")));f.put("size",bytes.length);f.put("sha256",sha(bytes));return obj("parserVersion","adv-java-1.0-photo","status","PARSED","parsedAt",now(),"file",f,"dataType","Реклама","context",context,"title",obj("region",context.get("region"),"municipality",context.get("municipality")),"referenceLists",references(rows(zip,sheets.get(NAMES.get(6)),shared)),"availableSheets",new ArrayList<String>(sheets.keySet()),"sheets",business,"totalRows",rowCount);
        }}catch(XMLStreamException | ZipException invalid){throw new IllegalArgumentException("Некорректный файл XLSX: "+invalid.getClass().getSimpleName(),invalid);}finally{Files.deleteIfExists(temp);}
    }
}
